gamesEl.onclick=e=>{
 const b=e.target.closest('.download');
 if(!b)return;
 const i=+b.dataset.i;
 if(installed.includes(i)){startGame(i);return}
 if(downloading)return;
 downloading=true;
 let p=0;
 const bar=b.parentElement.querySelector('.progress i');
 b.textContent='BAIXANDO';
 const t=setInterval(()=>{
  p+=4+Math.random()*8;
  if(p>=100){
   clearInterval(t);p=100;
   installed.push(i);
   localStorage.setItem('gcity-installed',JSON.stringify(installed));
   b.textContent='JOGAR';bar.style.width='100%';downloading=false;renderStore();
  }else{bar.style.width=p+'%'}
 },160);
};

