function worldToScreen(x,y){return [(x-px)*.9+W/2,(y-py)*.45+H/2]} 
function draw(){if($('#game').classList.contains('hidden'))return;resize();const speed=vehicle?6:2.8;if(keys.ArrowUp||keys.w)py-=speed;if(keys.ArrowDown||keys.s)py+=speed;if(keys.ArrowLeft||keys.a)px-=speed;if(keys.ArrowRight||keys.d)px+=speed;px=Math.max(80,Math.min(920,px));py=Math.max(80,Math.min(920,py));
ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.fillStyle='#65a77a';ctx.fillRect(0,0,W/devicePixelRatio,H/devicePixelRatio);
ctx.save();ctx.translate(W/devicePixelRatio/2-px*.9,H/devicePixelRatio/2-py*.45);ctx.scale(.9,.45);
ctx.fillStyle='#30383a';ctx.fillRect(120,120,800,800);ctx.fillStyle='#b9a87d';ctx.fillRect(450,120,160,800);ctx.fillRect(120,450,800,160);ctx.strokeStyle='#e7dbad';ctx.lineWidth=4;ctx.setLineDash([28,22]);ctx.beginPath();ctx.moveTo(530,120);ctx.lineTo(530,920);ctx.moveTo(120,530);ctx.lineTo(920,530);ctx.stroke();ctx.setLineDash([]);
// buildings
for(let x=180;x<440;x+=120)for(let y=180;y<420;y+=120){ctx.fillStyle='#d8bf8f';ctx.fillRect(x,y,90,90);ctx.fillStyle='#4f7185';ctx.fillRect(x+12,y+12,22,18);ctx.fillRect(x+52,y+12,22,18)}
for(let x=650;x<900;x+=100)for(let y=620;y<860;y+=100){ctx.fillStyle='#9caab0';ctx.fillRect(x,y,70,70)}
if(deliveryMode){ctx.fillStyle='rgba(82,255,177,.55)';ctx.beginPath();ctx.arc(820,820,22+Math.sin(Date.now()/160)*4,0,7);ctx.fill();ctx.fillStyle='#5cffb1';ctx.beginPath();ctx.moveTo(820,790);ctx.lineTo(840,820);ctx.lineTo(800,820);ctx.closePath();ctx.fill()}
// marker
const pulse=18+Math.sin(Date.now()/180)*5;ctx.fillStyle='rgba(255,202,45,.5)';ctx.beginPath();ctx.arc(530,350,pulse,0,7);ctx.fill();ctx.fillStyle='#ffd54a';ctx.beginPath();ctx.moveTo(530,320);ctx.lineTo(550,350);ctx.lineTo(510,350);ctx.closePath();ctx.fill();
// NPCs
npcs.forEach((n,i)=>{ctx.fillStyle=i===2?'#1e65ad':'#d4a14d';ctx.fillRect(n.x-10,n.y-28,20,28);ctx.fillStyle='#9c6545';ctx.beginPath();ctx.arc(n.x,n.y-34,9,0,7);ctx.fill()});
// player
ctx.fillStyle=vehicle?'#f13d42':'#141817';ctx.fillRect(px-18,py-35,36,35);ctx.fillStyle='#a86f50';ctx.beginPath();ctx.arc(px,py-43,12,0,7);ctx.fill();ctx.restore();
// distance and mission
if(!mission&&Math.hypot(px-530,py-350)<70){mission=true;missionStage=1;cinematic()}
if(deliveryMode&&Math.hypot(px-820,py-820)<65){deliveryMode=false;mission=false;missionStage=0;cash+=1500;$('#money').textContent='$ '+cash.toLocaleString();$('#missionhud').textContent=lang==='BR'?'MISSÃO CONCLUÍDA • +$1.500':'MISSION COMPLETE • +$1.500';engineBeep(.5,.4);speak(lang==='BR'?'Missão concluída. Você ganhou mil e cinco cento dólares.':'Mission complete. You earned one thousand five hundred dollars.')}
if(vehicle)engineBeep(.08,.05);requestAnimationFrame(draw)}requestAnimationFrame(draw);

